const buildWebsite = (name: string) => {
  const suffix = '.example.com';
  const protocol = 'https://';
  const maxSlugLength = 255 - protocol.length - suffix.length;
  const slug = faker.helpers
    .slugify(name)
    .toLowerCase()
    .slice(0, maxSlugLength);

  return `${protocol}${slug}${suffix}`;
};

