import { routeDefinitions } from '../routes/route-registry';

export const routeAccessRegistry = Object.fromEntries(
    routeDefinitions.map((definition) => [
        definition.id,
        {
            id: definition.id,
            path: `/${definition.path}`,
            menu: definition.menu,
            external: definition.external,
            public: definition.public
        }
    ])
);

export const defaultAllowedRouteIds = Object.values(routeAccessRegistry)
    .filter((routeDefinition) => routeDefinition.menu)
    .map((routeDefinition) => routeDefinition.id);

export function getDefaultAccessiblePath(allowedRouteIds) {
    const prioritizedRouteIds = routeDefinitions.filter((definition) => definition.menu && !definition.public).map((definition) => definition.id);

    const fallbackRouteId = prioritizedRouteIds.find((routeId) => allowedRouteIds.includes(routeId));

    return fallbackRouteId ? routeAccessRegistry[fallbackRouteId].path : null;
}
import PropTypes from 'prop-types';
import { createContext, useCallback, useMemo } from 'react';

import menuItems from 'mock/menu';

import { defaultAllowedRouteIds, routeAccessRegistry } from '../config/route-access.config';

export const RouteAccessContext = createContext(undefined);

function filterMenuItems(items, allowedRouteIds) {
  return items
    .map((item) => {
      if (item.type === 'group') {
        const children = filterMenuItems(item.children ?? [], allowedRouteIds);

        return children.length > 0 ? { ...item, children } : null;
      }

      const routeDefinition = routeAccessRegistry[item.id];

      if (!routeDefinition) {
        return null;
      }

      if (routeDefinition.public) {
        return item;
      }

      return allowedRouteIds.includes(item.id) ? item : null;
    })
    .filter(Boolean);
}

export function RouteAccessProvider({ children }) {
  const allowedRouteIds = defaultAllowedRouteIds;

  const filteredMenuGroups = useMemo(() => filterMenuItems(menuItems.items, allowedRouteIds), [allowedRouteIds]);

  const isRouteAllowed = useCallback(
    (routeId) => {
      const routeDefinition = routeAccessRegistry[routeId];

      if (!routeDefinition) {
        return false;
      }

      if (routeDefinition.public) {
        return true;
      }

      return allowedRouteIds.includes(routeId);
    },
    [allowedRouteIds]
  );

  const value = useMemo(
    () => ({
      allowedRouteIds,
      filteredMenuGroups,
      isRouteAllowed
    }),
    [allowedRouteIds, filteredMenuGroups, isRouteAllowed]
  );

  return <RouteAccessContext.Provider value={value}>{children}</RouteAccessContext.Provider>;
}

RouteAccessProvider.propTypes = { children: PropTypes.node };
