import { INestApplication } from '@nestjs/common';
import { DataSource } from 'typeorm';
import request from 'supertest';
import { createTestApp } from './setup/test-app';
import {
  closeTestDataSource,
  resetDatabaseSchema,
  truncateBusinessTables,
} from './setup/test-database';

jest.setTimeout(30000);

describe('Deal API (e2e)', () => {
  let app: INestApplication;
  let dataSource: DataSource;
  let companySeq = 0;
  let contactSeq = 0;
  let dealSeq = 0;

  beforeAll(async () => {
    await resetDatabaseSchema();
    app = await createTestApp();
    dataSource = app.get(DataSource);
    await truncateBusinessTables(dataSource);
  });

  afterAll(async () => {
    if (app) {
      await app.close();
    }

    await closeTestDataSource();
  });

  it('creates a deal and returns company summary on detail', async () => {
    // Verifies create persists all fields and detail includes company summary.
    const companyId = await createCompany('deal-create');
    const contactId = await createContact('deal-create', companyId);
    const payload = buildDealPayload('create', {
      companyId,
      contactId,
      stage: 'proposal',
      expectedCloseDate: '2026-12-10T08:00:00.000Z',
    });

    const createResponse = await request(app.getHttpServer())
      .post('/api/deals')
      .send(payload)
      .expect(201);

    expect(createResponse.body).toMatchObject({
      name: payload.name,
      value: payload.value,
      stage: payload.stage,
      companyId,
      contactId,
      expectedCloseDate: payload.expectedCloseDate,
    });

    const detailResponse = await request(app.getHttpServer())
      .get(`/api/deals/${createResponse.body.id}`)
      .expect(200);

    expect(detailResponse.body).toMatchObject({
      id: createResponse.body.id,
      name: payload.name,
      companyId,
      company: {
        id: companyId,
        name: `codex-e2e-company-deal-create-${companySeq}`,
      },
    });
  });

  it('uses stage=lead when stage is omitted', async () => {
    // Verifies omitted stage defaults to lead.
    const companyId = await createCompany('deal-default-stage');
    const payload = buildDealPayload('default-stage', { companyId });
    delete payload.stage;

    const createResponse = await request(app.getHttpServer())
      .post('/api/deals')
      .send(payload)
      .expect(201);

    expect(createResponse.body.stage).toBe('lead');
  });

  it('rejects missing required fields', async () => {
    // Verifies validation fails when required fields are missing.
    const response = await request(app.getHttpServer())
      .post('/api/deals')
      .send({
        stage: 'lead',
      })
      .expect(400);

    expect(response.body).toMatchObject({
      success: false,
      statusCode: 400,
      code: 'VALIDATION_ERROR',
    });
    expect(response.body.details.errors).toEqual(
      expect.arrayContaining([
        expect.objectContaining({ field: 'name' }),
        expect.objectContaining({ field: 'value' }),
        expect.objectContaining({ field: 'companyId' }),
      ]),
    );
  });

  it('returns NOT_FOUND when companyId or contactId is unknown', async () => {
    // Verifies unknown company/contact references are rejected.
    const unknownCompanyResponse = await request(app.getHttpServer())
      .post('/api/deals')
      .send(
        buildDealPayload('unknown-company', {
          companyId: '7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1aa',
        }),
      )
      .expect(404);

    expect(unknownCompanyResponse.body).toMatchObject({
      success: false,
      statusCode: 404,
      code: 'PARENT_NOT_FOUND',
    });

    const companyId = await createCompany('unknown-contact');
    const unknownContactResponse = await request(app.getHttpServer())
      .post('/api/deals')
      .send(
        buildDealPayload('unknown-contact', {
          companyId,
          contactId: '7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1ab',
        }),
      )
      .expect(404);

    expect(unknownContactResponse.body).toMatchObject({
      success: false,
      statusCode: 404,
      code: 'PARENT_NOT_FOUND',
    });
  });

  it('supports pagination, stage filter, companyId filter, and empty overflow pages', async () => {
    // Verifies list semantics and out-of-range behavior.
    const companyId = await createCompany('deal-list');
    const otherCompanyId = await createCompany('deal-list-other');

    await createDeal('list-1', {
      companyId,
      stage: 'qualified',
    });
    await createDeal('list-2', {
      companyId,
      stage: 'qualified',
    });
    await createDeal('list-3', {
      companyId,
      stage: 'proposal',
    });
    await createDeal('list-outside', {
      companyId: otherCompanyId,
      stage: 'qualified',
    });

    const response = await request(app.getHttpServer())
      .get(
        `/api/deals?companyId=${companyId}&stage=qualified&page=1&pageSize=1`,
      )
      .expect(200);

    expect(response.body.total).toBe(2);
    expect(response.body.page).toBe(1);
    expect(response.body.pageSize).toBe(1);
    expect(response.body.totalPages).toBe(2);
    expect(response.body.items).toHaveLength(1);
    expect(response.body.items[0]).toMatchObject({
      companyId,
      stage: 'qualified',
    });

    const overflowResponse = await request(app.getHttpServer())
      .get(
        `/api/deals?companyId=${companyId}&stage=qualified&page=3&pageSize=1`,
      )
      .expect(200);

    expect(overflowResponse.body.items).toEqual([]);
  });

  it('distinguishes INVALID_UUID from ENTITY_NOT_FOUND', async () => {
    // Verifies path id validation and not-found behavior.
    const invalidResponse = await request(app.getHttpServer())
      .get('/api/deals/not-a-uuid')
      .expect(400);

    expect(invalidResponse.body).toMatchObject({
      success: false,
      statusCode: 400,
      code: 'INVALID_UUID',
    });

    const missingResponse = await request(app.getHttpServer())
      .get('/api/deals/7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1ac')
      .expect(404);

    expect(missingResponse.body).toMatchObject({
      success: false,
      statusCode: 404,
      code: 'ENTITY_NOT_FOUND',
    });
  });

  it('updates mutable fields using a partial payload', async () => {
    // Verifies patch-style updates work with partial fields.
    const companyId = await createCompany('deal-update');
    const contactId = await createContact('deal-update', companyId);
    const dealId = await createDeal('update', {
      companyId,
      contactId,
      stage: 'lead',
      value: 5000,
    });

    const updateResponse = await request(app.getHttpServer())
      .post(`/api/deals/${dealId}`)
      .send({
        stage: 'negotiation',
        value: 7500,
      })
      .expect(201);

    expect(updateResponse.body).toMatchObject({
      id: dealId,
      stage: 'negotiation',
      value: 7500,
    });
  });

  it('rejects empty updates and unknown update fields', async () => {
    // Verifies update validation for empty payloads and unknown fields.
    const companyId = await createCompany('deal-update-validation');
    const dealId = await createDeal('update-validation', {
      companyId,
    });

    const emptyResponse = await request(app.getHttpServer())
      .post(`/api/deals/${dealId}`)
      .send({})
      .expect(400);

    expect(emptyResponse.body).toMatchObject({
      success: false,
      statusCode: 400,
      code: 'VALIDATION_ERROR',
    });


    const unknownFieldResponse = await request(app.getHttpServer())
      .post(`/api/deals/${dealId}`)
      .send({
        extraField: 'blocked',
      })
      .expect(400);

    expect(unknownFieldResponse.body).toMatchObject({
      success: false,
      statusCode: 400,
      code: 'VALIDATION_ERROR',
    });
    expect(unknownFieldResponse.body.details.errors).toEqual(
      expect.arrayContaining([
        expect.objectContaining({ field: 'extraField' }),
      ]),
    );
  });

  it('supports null contactId and null expectedCloseDate in create/list/detail/update', async () => {
    // Verifies nullable relation/date fields behave across read and write surfaces.
    const companyId = await createCompany('deal-nulls');
    const dealId = await createDeal('nulls', {
      companyId,
      contactId: null,
      expectedCloseDate: null,
      stage: 'qualified',
    });

    const listResponse = await request(app.getHttpServer())
      .get(`/api/deals?companyId=${companyId}&stage=qualified&page=1&pageSize=10`)
      .expect(200);

    expect(
      listResponse.body.items.find((item: { id: string }) => item.id === dealId),
    ).toMatchObject({
      id: dealId,
      contactId: null,
      expectedCloseDate: null,
    });

    const detailResponse = await request(app.getHttpServer())
      .get(`/api/deals/${dealId}`)
      .expect(200);

    expect(detailResponse.body).toMatchObject({
      id: dealId,
      contactId: null,
      expectedCloseDate: null,
    });

    const updateResponse = await request(app.getHttpServer())
      .post(`/api/deals/${dealId}`)
      .send({
        contactId: null,
        expectedCloseDate: null,
      })
      .expect(201);

    expect(updateResponse.body).toMatchObject({
      id: dealId,
      contactId: null,
      expectedCloseDate: null,
    });
  });

