const DEMO_PREFIX = 'Demo Seed Company';
const STATUSES = [
  CompanyStatus.ACTIVE,
  CompanyStatus.INACTIVE,
  CompanyStatus.PENDING,
] as const;
const INDUSTRIES = [
  Industry.TECHNOLOGY,
  Industry.FINANCE,
  Industry.MANUFACTURING,
  Industry.RETAIL,
  Industry.OTHER,
] as const;
const DEAL_STAGES = [
  'lead',
  'qualified',
  'proposal',
  'negotiation',
  'closed-won',
  'closed-lost',
] as const;

const daysFromNow = (now: Date, days: number) => {
  const date = new Date(now);
  date.setDate(date.getDate() + days);
  date.setHours(17, 0, 0, 0);

  return date;
};

const createDemoCompanies = async ({ dataSource, now }: SeedContext) => {
  const companyRepository = dataSource.getRepository(CompanyEntity);
  const contactRepository = dataSource.getRepository(ContactEntity);
  const dealRepository = dataSource.getRepository(DealEntity);
  let contactsCreated = 0;
  let dealsCreated = 0;
  const companiesWithContacts: Array<{ id: string; contacts: string[] }> = [];

  await cleanupCompaniesByPrefixes({ dataSource, now }, [DEMO_PREFIX]);

  for (let companyIndex = 0; companyIndex < 10; companyIndex += 1) {
    const companyName = `${DEMO_PREFIX} ${String(companyIndex + 1).padStart(2, '0')}`;
    const company = await companyRepository.save(
      companyRepository.create(
        buildCompany({
          name: companyName,
          status: STATUSES[companyIndex % STATUSES.length],
          industry: INDUSTRIES[companyIndex % INDUSTRIES.length],
          lastContactedAt: distributeRecentDate(now, companyIndex, 10),
          email: `demo-company-${companyIndex + 1}@baseline.local`,
        }),
      ),
    );
    const contactIds: string[] = [];

    const contactsForCompany = 2 + (companyIndex % 4);

    for (
      let contactIndex = 0;
      contactIndex < contactsForCompany;
      contactIndex += 1
    ) {
      contactsCreated += 1;

      const contact = await contactRepository.save(
        contactRepository.create(
          buildContact({
            companyId: company.id,
            name: faker.person.fullName(),
            lastContactedAt: distributeRecentDate(
              now,
              companyIndex + contactIndex,
              14,
            ),
            email: `demo-contact-${companyIndex + 1}-${contactIndex + 1}@baseline.local`,
            role: [
              'Decision Maker',
              'User',
              'Finance Reviewer',
              'Technical Buyer',
            ][contactIndex % 4],
          }),
        ),
      );

      contactIds.push(contact.id);
    }

    companiesWithContacts.push({
      id: company.id,
      contacts: contactIds,
    });
  }

  for (let dealIndex = 0; dealIndex < 12; dealIndex += 1) {
    const companyRef =
      companiesWithContacts[dealIndex % companiesWithContacts.length];
    const stage = DEAL_STAGES[dealIndex % DEAL_STAGES.length];
    const contactId =
      dealIndex % 4 === 0
        ? null
        : (companyRef.contacts[dealIndex % companyRef.contacts.length] ?? null);

    await dealRepository.save(
      dealRepository.create(
        buildDeal({
          companyId: companyRef.id,
          contactId,
          name: `Demo Deal ${String(dealIndex + 1).padStart(2, '0')} ${stage}`,
          stage,
          value: 6_000 + dealIndex * 2_500,
          expectedCloseDate: daysFromNow(now, 10 + dealIndex * 3),
        }),
      ),
    );

    dealsCreated += 1;
  }

  return {
    contactsCreated,
    dealsCreated,
  };
};

export const demoSeedScenario: SeedScenario = {
  name: 'demo',
  async run(context) {
    faker.seed(20260703);

    const { contactsCreated, dealsCreated } =
