              <DataTablePagination
                page={dealPage.page}
                pageSize={dealPage.pageSize}
                total={dealPage.total}
                totalPages={dealPage.totalPages}
                onPageChange={(page) => setListQuery((current) => ({ ...current, page }))}
                onPageSizeChange={(pageSize) =>
                  setListQuery((current) => ({ ...current, page: 1, pageSize }))
                }
              />
            </Box>
          ) : null
        }
      >
        <DealTable
          deals={dealItems}
          companyNameById={companyNameById}
          onDelete={setDeleteTarget}
          onEdit={(deal) =>
            setFormState({
              open: true,
              mode: 'edit',
              deal,
            })
          }
          onView={(deal) => navigate(`/deals/${deal.id}`)}
        />
      </DataTableShell>

      <DealFormDialog
        open={formState.open}
        mode={formState.mode}
        initialValues={formState.deal}
        isPending={createDeal.isPending || updateDeal.isPending}
        onClose={() => setFormState({ open: false, mode: 'create', deal: null })}
        onSubmit={handleFormSubmit}

    await expect(listConstraintNames(dataSource, 'deals')).resolves.toEqual(
      expect.arrayContaining(['fk_deals_company_id', 'fk_deals_contact_id']),
    );
    await expect(listIndexNames(dataSource, 'deals')).resolves.toEqual(
      expect.arrayContaining([
        'idx_deals_company_id',
        'idx_deals_contact_id',
        'idx_deals_stage',
      ]),
    );
  });

  it('rolls back the migration', async () => {
    // Verifies rolling back the latest migration removes deal artifacts only.
    await dataSource.runMigrations();
    await dataSource.undoLastMigration();

    await expect(listConstraintNames(dataSource, 'deals')).resolves.not.toEqual(
      expect.arrayContaining(['fk_deals_company_id', 'fk_deals_contact_id']),
    );
    await expect(listIndexNames(dataSource, 'deals')).resolves.not.toEqual(
      expect.arrayContaining([
        'idx_deals_company_id',
        'idx_deals_contact_id',
        'idx_deals_stage',
      ]),
    );
    await expect(
      listConstraintNames(dataSource, 'contacts'),
    ).resolves.toContain('fk_contacts_company_id');
  });

  it('can rerun the migration after rollback', async () => {
    // Verifies the latest migration can be applied again after rollback.
    await dataSource.runMigrations();
    await dataSource.undoLastMigration();
    await dataSource.runMigrations();

    await expect(listConstraintNames(dataSource, 'deals')).resolves.toEqual(
      expect.arrayContaining(['fk_deals_company_id', 'fk_deals_contact_id']),
    );
  });

  it('prevents orphan companyId values', async () => {
    // Verifies the foreign key blocks orphan contact rows.
    await dataSource.runMigrations();

    await expect(
      dataSource.query(
        `
          INSERT INTO "contacts" ("id", "companyId", "name", "email", "phone", "role", "createdAt", "updatedAt")
          VALUES (gen_random_uuid(), $1, 'Orphan Contact', 'orphan@test.local', '0200-7777', 'User', NOW(), NOW())
        `,
        ['7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1aa'],
      ),
    ).rejects.toThrow(/fk_contacts_company_id/i);
  });

  it('prevents orphan foreign keys on deals', async () => {
    // Verifies deal company/contact foreign keys reject orphan references.
    await dataSource.runMigrations();

    await expect(
      dataSource.query(
        `
          INSERT INTO "deals" ("id", "name", "value", "stage", "companyId", "contactId", "createdAt", "updatedAt")
          VALUES (gen_random_uuid(), 'Orphan Deal Company', 1000, 'lead', $1, NULL, NOW(), NOW())
        `,
        ['7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1aa'],
      ),
    ).rejects.toThrow(/fk_deals_company_id/i);

    const [{ id: companyId }] = await dataSource.query(
      `
        INSERT INTO "companies" ("id", "name", "status", "createdAt", "updatedAt")
        VALUES (gen_random_uuid(), 'Deal FK Company', '1', NOW(), NOW())
        RETURNING "id"
      `,
    );

    await expect(
      dataSource.query(
        `
          INSERT INTO "deals" ("id", "name", "value", "stage", "companyId", "contactId", "createdAt", "updatedAt")
          VALUES (gen_random_uuid(), 'Orphan Deal Contact', 1000, 'lead', $1, $2, NOW(), NOW())
        `,
        [companyId, '7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1ab'],
      ),
    ).rejects.toThrow(/fk_deals_contact_id/i);
  });
});

